/* The supplied manual tool is isolated from the existing automatic transit modes. */
(()=>{'use strict';const $=id=>document.getElementById(id),NAMES={Su:'Sun',Mo:'Moon',Ma:'Mars',Me:'Mercury',Ju:'Jupiter',Ve:'Venus',Sa:'Saturn',Ra:'Rahu',Ke:'Ketu'};let opened=false,context=null,frame=null,revision=0;
function linkedPeriods(path=[],chooseCurrent=false){const data=KPHomeDasha.getData();if(!data.ready)throw Error('Calculate the natal chart first.');const offset=Number(data.timeZoneHours)*3600000,now=Date.now()+offset,options=[],selection=[];let rows=data.levels[0].rows,lower=-Infinity,upper=Infinity,chosen=null;for(let depth=0;depth<4;depth++){const valid=rows.map(row=>({...row,startMs:Math.max(row.startMs,lower),endMs:Math.min(row.endMs,upper)})).filter(row=>row.endMs>row.startMs),items=valid.map((row,index)=>{const id=KPDisplay.idByName[row.lord]||row.lord;return {key:String(index),id,name:NAMES[id]||row.lord,startUTC:new Date(row.startMs-offset).toISOString(),endUTC:new Date(row.endMs-offset).toISOString()};});options.push(items);let index=chooseCurrent?valid.findIndex(row=>row.startMs<=now&&now<row.endMs):Number.isInteger(path[depth])?path[depth]:0;if(depth===3&&(chooseCurrent||path[depth]===null||path[depth]===undefined)){selection.push(null);break;}if(index<0||index>=valid.length)index=0;selection.push(index);chosen=valid[index];if(!chosen)throw Error('No valid connected DBA periods.');lower=chosen.startMs;upper=chosen.endMs;rows=KPHomeDasha.subdivide(chosen);}const range=options[selection[3]===null?2:3]?.[selection[selection[3]===null?2:3]];return {options,path:selection,from:new Date(Date.parse(range.startUTC)+offset).toISOString().slice(0,10),to:new Date(Date.parse(range.endUTC)-1+offset).toISOString().slice(0,10)};}
function theme(){const p=KPPreferences.get();return {header:p.themeHeader,background:p.themeBackground,stripe:p.themeStripe,button:p.themeButton,ink:p.fontColor,dark:p.themeType==='dark'};}
function outerLongitude(date,id,siderealSun){const A=window.Astronomy,tropical=body=>A.Ecliptic(A.GeoVector(A.Body[body],new Date(date+'T00:00:00Z'),true)).elon,ayan=tropical('Sun')-siderealSun;return ((tropical(id)-ayan)%360+360)%360;}
function selectedEvent(){const select=$('tr-event'),option=select?.selectedOptions[0];if(!option||option.disabled||!select.value)throw Error('Select a valid event before searching transits.');return {id:select.value,name:option.textContent.trim(),cusp:$('tr-main-cusp')?.value||'all',significators:KPTransit.significators().map(row=>({id:row.id,name:NAMES[row.id]||row.id}))};}
function currentContext(){
 const now=Date.now(),data=KPTransit.currentPeriods(now),offset=Number(data.timeZoneHours)*3600000,periods={};
 for(const level of ['MD','AD','PD']){const row=data.periods[level];periods[level]={id:row.id,name:NAMES[row.id]||row.lord,startUTC:row.startUTC,endUTC:row.endUTC};}
 const sd=KPHomeDasha.subdivide(data.periods.PD).find(row=>row.startMs<=now+offset&&now+offset<row.endMs);if(sd){const id=KPDisplay.idByName[sd.lord]||sd.lord;periods.SD={id,name:NAMES[id]||sd.lord,startUTC:new Date(sd.startMs-offset).toISOString(),endUTC:new Date(sd.endMs-offset).toISOString()};}
 const model=window.currentKPModel,point=p=>p?{sign:p.sign||KPDisplay.longitudeDetails(p.longitude).sign,nak:p.nakshatra||KPDisplay.longitudeDetails(p.longitude).nakshatra}:null;
 return {event:selectedEvent(),linked:linkedPeriods([],true),theme:theme(),periods,instant:new Date(now).toISOString(),offsetMinutes:offset/60000,native:$('name')?.value||'',from:new Date(Date.parse(periods.PD.startUTC)+offset).toISOString().slice(0,10),to:new Date(Date.parse(periods.PD.endUTC)-1+offset).toISOString().slice(0,10),moon:point(model?.planets?.find(p=>p.id==='Mo')),asc:point(model?.houses?.find(h=>h.id===1))};
}
function renderCurrent(){const cards=$('manual-current-dba');cards.replaceChildren();for(const level of ['MD','AD','PD']){const row=context.periods[level],card=document.createElement('article'),title=document.createElement('strong'),dates=document.createElement('span');card.dataset.level=level;card.dataset.planet=row.id;title.textContent=level+' · '+row.name;const local=iso=>{const stamp=new Date(Date.parse(iso)+context.offsetMinutes*60000).toISOString();return KPPreferences.formatDate(stamp.slice(0,10))+' '+stamp.slice(11,19);};dates.textContent=local(row.startUTC)+' → '+local(row.endUTC);card.append(title,dates);cards.append(card);}$('manual-transit-status').textContent='Current DBA · '+context.native+' · local chart time · end exclusive. The manual tool uses daily 05:30 IST samples.';}
function loadFrame(token){if(!opened||token!==revision)return;if(frame?.contentWindow?.KPManualTransitTool){frame.contentWindow.KPManualTransitTool.applyContext(context);return;}if(frame)return;frame=document.createElement('iframe');frame.id='manual-transit-frame';frame.title='Manually Search Transit · supplied KP tool';frame.setAttribute('referrerpolicy','no-referrer');frame.addEventListener('load',()=>{if(opened&&context&&frame.contentWindow.KPManualTransitTool)frame.contentWindow.KPManualTransitTool.applyContext(context);});frame.srcdoc=JSON.parse($('kp-manual-transit-document').textContent);$('manual-transit-tool-mount').append(frame);}
function refresh(){const token=++revision;try{context=currentContext();renderCurrent();requestAnimationFrame(()=>setTimeout(()=>loadFrame(token),0));}catch(error){context=null;$('manual-current-dba').replaceChildren();$('manual-transit-status').textContent=error.message;}}
function open(){if(window.KPCustomerFeatures&&!window.KPCustomerFeatures.allowed('transit'))return;KPTransitWorkspace.cancel();opened=true;$('transit').classList.add('tr-manual-open');for(const n of $('transit').querySelectorAll('.tr-simple-choice,#tr-simple-cusp-choice,#tr-simple-event-choice,.tr-event-query'))n.hidden=false;$('tr-handy-title').textContent='Manually Search Transit';for(const button of document.querySelectorAll('[data-tr-search-mode]'))button.setAttribute('aria-pressed','false');$('manual-transit-open').setAttribute('aria-pressed','true');refresh();}
function close(){opened=false;revision++;$('transit')?.classList.remove('tr-manual-open');$('manual-transit-open')?.setAttribute('aria-pressed','false');}
function preview(){try{const report=frame?.contentWindow?.KPManualTransitTool?.report();if(!report)throw Error('Compute manual transit results before printing.');KPChildGenderSheet.preview({title:'Manual Transit Report',html:report.html,css:report.css,lang:'english'});}catch(error){$('manual-transit-status').textContent=error.message;}}
function init(){const modes=$('transit')?.querySelector('.tr-handy-modes');if(!modes)return;const button=document.createElement('button');button.id='manual-transit-open';button.type='button';button.textContent='Manually Search Transit';button.setAttribute('aria-pressed','false');button.addEventListener('click',open);modes.append(button);const section=document.createElement('section');section.id='manual-transit-panel';section.setAttribute('data-no-localize','');section.innerHTML='<div class="manual-transit-heading"><h3>Current DBA</h3><button id="manual-transit-current" type="button">Use current DBA</button></div><div id="manual-current-dba" aria-live="polite"></div><p id="manual-transit-status" role="status"></p><div id="manual-transit-tool-mount"></div>';modes.after(section);$('manual-transit-current').addEventListener('click',refresh);$('transit').addEventListener('change',event=>{if(opened&&['tr-event','tr-main-cusp','tr-significator-method','tr-houses'].includes(event.target.id))setTimeout(()=>{try{const selected=selectedEvent();context.event=selected;frame?.contentWindow?.KPManualTransitTool?.setEvent(selected);}catch(error){frame?.contentWindow?.KPManualTransitTool?.setEvent(null);$('manual-transit-status').textContent=error.message;}},0);});section.addEventListener('change',event=>event.stopPropagation());window.addEventListener('kp-preferences-changed',()=>frame?.contentWindow?.KPManualTransitTool?.applyTheme(theme()));window.addEventListener('chart-manual-change',()=>{if(opened)refresh();});window.addEventListener('chart-saved',()=>{if(opened)refresh();});}
window.KPManualTransit=Object.freeze({open,close,preview,refresh,selectedEvent,linkedPeriods,outerLongitude,longitudeDetails:arc=>KPDisplay.longitudeDetails(arc),isOpen:()=>opened,getContext:()=>context?structuredClone(context):null});if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,300));else setTimeout(init,300);})();
